-- N5-1: コンビニでの買い物
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'コンビニでの買い物',
  '店員：いらっしゃいませ。\n田中：すみません、おにぎりはどこですか。\n店員：おにぎりはあちらの棚にあります。\n田中：ありがとうございます。これと、お茶をください。\n店員：はい、おにぎり一つとお茶一つですね。全部で三百二十円です。\n田中：千円でお願いします。\n店員：六百八十円のおつりです。レジ袋はいりますか。\n田中：いいえ、大丈夫です。ありがとうございます。',
  'dialogue',
  'N5',
  ARRAY['店員', '田中'],
  'コンビニでおにぎりとお茶を買う場面',
  '[{"word":"棚","reading":"たな","meaning_ko":"선반"},{"word":"全部","reading":"ぜんぶ","meaning_ko":"전부"},{"word":"おつり","reading":"おつり","meaning_ko":"거스름돈"},{"word":"レジ袋","reading":"レジぶくろ","meaning_ko":"비닐봉지"},{"word":"大丈夫","reading":"だいじょうぶ","meaning_ko":"괜찮다"}]'::jsonb,
  '점원: 어서 오세요.\n다나카: 저기요, 주먹밥은 어디에 있나요?\n점원: 주먹밥은 저쪽 선반에 있습니다.\n다나카: 감사합니다. 이것과 차 주세요.\n점원: 네, 주먹밥 하나와 차 하나요. 전부 320엔입니다.\n다나카: 천 엔으로 부탁합니다.\n점원: 680엔 거스름돈입니다. 비닐봉지 필요하세요?\n다나카: 아니요, 괜찮습니다. 감사합니다.',
  1
);

-- N5-2: 駅で道を聞く
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '駅で道を聞く',
  '山田：すみません、図書館はどこですか。\n鈴木：図書館ですか。ここからまっすぐ行ってください。\n山田：まっすぐですか。\n鈴木：はい、まっすぐ行って、二つ目の信号を右に曲がってください。\n山田：二つ目の信号を右ですね。\n鈴木：そうです。右に曲がったら、左側にあります。\n山田：歩いてどのくらいかかりますか。\n鈴木：十分くらいですよ。\n山田：ありがとうございます。',
  'dialogue',
  'N5',
  ARRAY['山田', '鈴木'],
  '駅の近くで図書館への道を聞く場面',
  '[{"word":"図書館","reading":"としょかん","meaning_ko":"도서관"},{"word":"まっすぐ","reading":"まっすぐ","meaning_ko":"곧장"},{"word":"信号","reading":"しんごう","meaning_ko":"신호등"},{"word":"曲がる","reading":"まがる","meaning_ko":"돌다"},{"word":"左側","reading":"ひだりがわ","meaning_ko":"왼쪽"},{"word":"歩いて","reading":"あるいて","meaning_ko":"걸어서"}]'::jsonb,
  '야마다: 저기요, 도서관은 어디에 있나요?\n스즈키: 도서관이요? 여기서 곧장 가세요.\n야마다: 곧장이요?\n스즈키: 네, 곧장 가서 두 번째 신호등에서 오른쪽으로 도세요.\n야마다: 두 번째 신호등에서 오른쪽이요.\n스즈키: 맞아요. 오른쪽으로 돌면 왼쪽에 있습니다.\n야마다: 걸어서 얼마나 걸리나요?\n스즈키: 10분 정도예요.\n야마다: 감사합니다.',
  2
);

-- N5-3: レストランで注文
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'レストランで注文',
  '店員：いらっしゃいませ。何名様ですか。\n佐藤：二人です。\n店員：こちらの席にどうぞ。メニューです。\n佐藤：ありがとうございます。\n高橋：何にする？\n佐藤：私はカレーライスにする。高橋さんは？\n高橋：私はラーメンにします。\n店員：ご注文はお決まりですか。\n佐藤：カレーライス一つとラーメン一つ、お願いします。\n店員：お飲み物はいかがですか。\n高橋：水をください。\n店員：かしこまりました。少々お待ちください。',
  'dialogue',
  'N5',
  ARRAY['店員', '佐藤', '高橋'],
  'レストランで二人で食事を注文する場面',
  '[{"word":"何名様","reading":"なんめいさま","meaning_ko":"몇 분"},{"word":"席","reading":"せき","meaning_ko":"좌석"},{"word":"注文","reading":"ちゅうもん","meaning_ko":"주문"},{"word":"飲み物","reading":"のみもの","meaning_ko":"음료"},{"word":"かしこまりました","reading":"かしこまりました","meaning_ko":"알겠습니다(정중)"}]'::jsonb,
  '점원: 어서 오세요. 몇 분이세요?\n사토: 두 명이요.\n점원: 이쪽 자리로 앉으세요. 메뉴입니다.\n사토: 감사합니다.\n다카하시: 뭐로 할래?\n사토: 나는 카레라이스로 할게. 다카하시 씨는?\n다카하시: 저는 라멘으로 하겠습니다.\n점원: 주문하시겠어요?\n사토: 카레라이스 하나와 라멘 하나 부탁합니다.\n점원: 음료는 어떻게 하시겠어요?\n다카하시: 물 주세요.\n점원: 알겠습니다. 잠시만 기다려 주세요.',
  3
);

-- N5-4: 友達との電話
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '友達との電話',
  '山田：もしもし、鈴木さん？\n鈴木：あ、山田さん、こんにちは。\n山田：土曜日、ひまですか。\n鈴木：土曜日？うん、ひまだよ。\n山田：じゃあ、一緒に公園に行きませんか。\n鈴木：いいね！何時に会う？\n山田：十時はどうですか。\n鈴木：十時はちょっと早いな。十一時はどう？\n山田：十一時、いいですよ。駅の前で会いましょう。\n鈴木：分かった。楽しみだね。じゃあ、また土曜日に。\n山田：うん、じゃあね。',
  'dialogue',
  'N5',
  ARRAY['山田', '鈴木'],
  '友達に電話して週末の予定を相談する場面',
  '[{"word":"ひま","reading":"ひま","meaning_ko":"한가하다"},{"word":"一緒に","reading":"いっしょに","meaning_ko":"함께"},{"word":"公園","reading":"こうえん","meaning_ko":"공원"},{"word":"早い","reading":"はやい","meaning_ko":"이르다"},{"word":"楽しみ","reading":"たのしみ","meaning_ko":"기대"}]'::jsonb,
  '야마다: 여보세요, 스즈키 씨?\n스즈키: 아, 야마다 씨, 안녕하세요.\n야마다: 토요일에 시간 있어요?\n스즈키: 토요일? 응, 한가해.\n야마다: 그럼 같이 공원에 가지 않을래요?\n스즈키: 좋아! 몇 시에 만날까?\n야마다: 10시는 어때요?\n스즈키: 10시는 좀 이른데. 11시는 어때?\n야마다: 11시 좋아요. 역 앞에서 만나요.\n스즈키: 알았어. 기대된다. 그럼 토요일에.\n야마다: 응, 그럼.',
  4
);

-- N5-5: 天気のお知らせ
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '天気のお知らせ',
  'アナウンサー：天気のお知らせです。今日の東京の天気は晴れです。気温は二十五度です。明日は曇りで、午後から雨が降るでしょう。傘を持って出かけてください。週末は晴れて、暑くなります。水をたくさん飲んでください。以上、天気のお知らせでした。',
  'announcement',
  'N5',
  ARRAY['アナウンサー'],
  'テレビの天気予報のお知らせ',
  '[{"word":"晴れ","reading":"はれ","meaning_ko":"맑음"},{"word":"気温","reading":"きおん","meaning_ko":"기온"},{"word":"曇り","reading":"くもり","meaning_ko":"흐림"},{"word":"傘","reading":"かさ","meaning_ko":"우산"},{"word":"暑い","reading":"あつい","meaning_ko":"덥다"}]'::jsonb,
  '아나운서: 날씨 안내입니다. 오늘 도쿄의 날씨는 맑음입니다. 기온은 25도입니다. 내일은 흐리고 오후부터 비가 올 것입니다. 우산을 가지고 나가세요. 주말은 맑고 더워질 것입니다. 물을 많이 마시세요. 이상 날씨 안내였습니다.',
  5
);

