-- N4-1: 病院での受診
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '病院での受診',
  '受付：おはようございます。保険証をお願いします。\n田中：はい、これです。\n受付：田中さんですね。今日はどうされましたか。\n田中：三日前から頭が痛くて、熱もあるんです。\n受付：そうですか。少しお待ちください。\n医者：田中さん、どうぞお入りください。いつから具合が悪いですか。\n田中：三日前からです。頭が痛くて、咳も出ます。\n医者：熱を測りましょう。三十八度二分ですね。のどを見せてください。\n田中：はい。\n医者：のどが赤いですね。風邪だと思います。薬を出しますから、三日分飲んでください。\n田中：分かりました。食事の前に飲みますか。\n医者：いいえ、食事の後に飲んでください。お大事に。',
  'dialogue',
  'N4',
  ARRAY['受付', '田中', '医者'],
  '病院で風邪の症状を医者に伝えて診察を受ける場面',
  '[{"word":"保険証","reading":"ほけんしょう","meaning_ko":"보험증"},{"word":"具合","reading":"ぐあい","meaning_ko":"상태, 컨디션"},{"word":"咳","reading":"せき","meaning_ko":"기침"},{"word":"のど","reading":"のど","meaning_ko":"목"},{"word":"風邪","reading":"かぜ","meaning_ko":"감기"},{"word":"薬","reading":"くすり","meaning_ko":"약"}]'::jsonb,
  '접수: 안녕하세요. 보험증 부탁드립니다.\n다나카: 네, 여기요.\n접수: 다나카 씨군요. 오늘은 어떻게 오셨나요?\n다나카: 3일 전부터 머리가 아프고 열도 있어요.\n접수: 그렇군요. 잠시만 기다려 주세요.\n의사: 다나카 씨, 들어오세요. 언제부터 상태가 안 좋으세요?\n다나카: 3일 전부터요. 머리가 아프고 기침도 나요.\n의사: 열을 재봅시다. 38도 2분이네요. 목을 보여주세요.\n다나카: 네.\n의사: 목이 빨갛네요. 감기인 것 같습니다. 약을 처방해 드릴 테니 3일분 드세요.\n다나카: 알겠습니다. 식사 전에 먹나요?\n의사: 아니요, 식사 후에 드세요. 몸조리 잘 하세요.',
  6
);

-- N4-2: 不動産屋でのアパート探し
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '不動産屋でのアパート探し',
  '店員：いらっしゃいませ。お部屋をお探しですか。\n佐藤：はい、一人暮らし用のアパートを探しています。\n店員：ご予算はどのくらいですか。\n佐藤：月六万円ぐらいがいいです。\n店員：駅からの距離はどうですか。\n佐藤：歩いて十分以内がいいんですが。\n店員：この物件はいかがですか。駅から歩いて七分で、家賃は五万八千円です。\n佐藤：いいですね。部屋の広さはどのくらいですか。\n店員：ワンルームで、二十平米です。バス・トイレ別です。\n佐藤：洗濯機は置けますか。\n店員：はい、ベランダに洗濯機置き場があります。\n佐藤：いいですね。一度見に行ってもいいですか。\n店員：もちろんです。今週の土曜日はいかがですか。',
  'dialogue',
  'N4',
  ARRAY['店員', '佐藤'],
  '不動産屋でアパートの条件を相談し、物件を探す場面',
  '[{"word":"一人暮らし","reading":"ひとりぐらし","meaning_ko":"자취, 혼자 사는 것"},{"word":"予算","reading":"よさん","meaning_ko":"예산"},{"word":"物件","reading":"ぶっけん","meaning_ko":"매물"},{"word":"家賃","reading":"やちん","meaning_ko":"집세"},{"word":"平米","reading":"へいべい","meaning_ko":"평방미터"},{"word":"ベランダ","reading":"ベランダ","meaning_ko":"베란다"}]'::jsonb,
  '직원: 어서 오세요. 방을 찾고 계신가요?\n사토: 네, 혼자 살 아파트를 찾고 있어요.\n직원: 예산은 어느 정도인가요?\n사토: 월 6만 엔 정도가 좋겠어요.\n직원: 역에서의 거리는 어떤가요?\n사토: 걸어서 10분 이내가 좋은데요.\n직원: 이 매물은 어떠세요? 역에서 걸어서 7분이고, 월세는 5만 8천 엔입니다.\n사토: 좋네요. 방 크기는 어느 정도예요?\n직원: 원룸이고 20제곱미터입니다. 욕실과 화장실이 분리되어 있어요.\n사토: 세탁기는 놓을 수 있나요?\n직원: 네, 베란다에 세탁기 놓는 곳이 있습니다.\n사토: 좋네요. 한번 보러 가도 될까요?\n직원: 물론이죠. 이번 주 토요일은 어떠세요?',
  7
);

-- N4-3: 郵便局での手続き
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '郵便局での手続き',
  '高橋：すみません、この荷物を韓国に送りたいんですが。\n局員：韓国ですね。中身は何ですか。\n高橋：お菓子と本です。\n局員：重さを量りますね。二キロです。送り方は航空便と船便がありますが。\n高橋：航空便でお願いします。どのくらいかかりますか。\n局員：航空便ですと、三日から五日ぐらいで届きます。料金は二千五百円です。\n高橋：じゃあ、航空便でお願いします。\n局員：こちらの伝票に送り先の住所とお名前を書いてください。\n高橋：分かりました。ここでいいですか。\n局員：はい、大丈夫です。壊れやすい物はありますか。\n高橋：いいえ、ありません。\n局員：では、二千五百円になります。',
  'dialogue',
  'N4',
  ARRAY['高橋', '局員'],
  '郵便局で韓国に荷物を送る手続きをする場面',
  '[{"word":"荷物","reading":"にもつ","meaning_ko":"짐, 소포"},{"word":"中身","reading":"なかみ","meaning_ko":"내용물"},{"word":"航空便","reading":"こうくうびん","meaning_ko":"항공편"},{"word":"届く","reading":"とどく","meaning_ko":"도착하다"},{"word":"伝票","reading":"でんぴょう","meaning_ko":"전표, 송장"},{"word":"壊れやすい","reading":"こわれやすい","meaning_ko":"깨지기 쉬운"}]'::jsonb,
  '다카하시: 저기요, 이 소포를 한국에 보내고 싶은데요.\n직원: 한국이군요. 내용물은 뭔가요?\n다카하시: 과자와 책이에요.\n직원: 무게를 재볼게요. 2킬로그램이네요. 배송 방법은 항공편과 선편이 있는데요.\n다카하시: 항공편으로 부탁합니다. 얼마나 걸리나요?\n직원: 항공편이면 3일에서 5일 정도에 도착합니다. 요금은 2,500엔입니다.\n다카하시: 그럼 항공편으로 부탁합니다.\n직원: 이 전표에 보내실 곳의 주소와 이름을 적어주세요.\n다카하시: 알겠습니다. 여기에 쓰면 되나요?\n직원: 네, 괜찮습니다. 깨지기 쉬운 물건이 있나요?\n다카하시: 아니요, 없습니다.\n직원: 그러면 2,500엔입니다.',
  8
);

-- N4-4: バスの案内放送
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'バスの案内放送',
  'アナウンス：ご乗車ありがとうございます。このバスは東京駅行きです。次は「中央公園前」です。中央公園、市立図書館にお越しの方はこちらでお降りください。お降りの際は、前のドアからお降りください。なお、本日は祝日ダイヤで運行しております。通常より本数が少なくなっておりますので、ご注意ください。次の「市役所前」は、降車ボタンでお知らせください。車内では携帯電話はマナーモードにしてください。ご協力をお願いいたします。',
  'announcement',
  'N4',
  ARRAY['アナウンス'],
  'バス車内での案内放送',
  '[{"word":"乗車","reading":"じょうしゃ","meaning_ko":"승차"},{"word":"お越し","reading":"おこし","meaning_ko":"오시는 것(경어)"},{"word":"祝日","reading":"しゅくじつ","meaning_ko":"공휴일"},{"word":"本数","reading":"ほんすう","meaning_ko":"운행 횟수"},{"word":"降車","reading":"こうしゃ","meaning_ko":"하차"},{"word":"携帯電話","reading":"けいたいでんわ","meaning_ko":"휴대전화"}]'::jsonb,
  '안내방송: 승차해 주셔서 감사합니다. 이 버스는 도쿄역 행입니다. 다음은 ''주오공원 앞''입니다. 주오공원, 시립도서관에 가시는 분은 여기서 내려주세요. 내리실 때는 앞문으로 내려주세요. 또한, 오늘은 공휴일 시간표로 운행하고 있습니다. 평소보다 운행 횟수가 적으니 주의해 주세요. 다음 ''시청 앞''은 하차 버튼으로 알려주세요. 차내에서는 휴대전화를 매너모드로 해주세요. 협조 부탁드립니다.',
  9
);

-- N4-5: 友人を旅行に誘う
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '友人を旅行に誘う',
  '山田：鈴木さん、来月の連休、どこか行かない？\n鈴木：いいね！どこに行きたい？\n山田：京都はどう？紅葉がきれいな時期だと思うんだけど。\n鈴木：京都いいね。でも、宿は取れるかな。\n山田：早めに予約すれば大丈夫だと思うよ。\n鈴木：交通手段はどうする？新幹線？\n山田：夜行バスのほうが安いよ。片道三千円ぐらいで行ける。\n鈴木：そんなに安いの？じゃあ、バスにしよう。\n山田：うん。一泊二日で、お寺とか回ろうよ。\n鈴木：いいね。抹茶のスイーツも食べたいな。\n山田：もちろん！じゃあ、詳しいことはまた連絡するね。\n鈴木：うん、楽しみにしてる！',
  'dialogue',
  'N4',
  ARRAY['山田', '鈴木'],
  '友人を京都旅行に誘い、計画を立てる場面',
  '[{"word":"連休","reading":"れんきゅう","meaning_ko":"연휴"},{"word":"紅葉","reading":"こうよう","meaning_ko":"단풍"},{"word":"宿","reading":"やど","meaning_ko":"숙소"},{"word":"夜行バス","reading":"やこうバス","meaning_ko":"야간버스"},{"word":"片道","reading":"かたみち","meaning_ko":"편도"},{"word":"一泊二日","reading":"いっぱくふつか","meaning_ko":"1박 2일"}]'::jsonb,
  '야마다: 스즈키 씨, 다음 달 연휴에 어디 안 갈래?\n스즈키: 좋아! 어디 가고 싶어?\n야마다: 교토는 어때? 단풍이 예쁜 시기일 거야.\n스즈키: 교토 좋다. 그런데 숙소 잡을 수 있을까?\n야마다: 일찍 예약하면 괜찮을 거야.\n스즈키: 교통수단은 어떻게 해? 신칸센?\n야마다: 야간버스가 더 싸. 편도 3천 엔 정도로 갈 수 있어.\n스즈키: 그렇게 싸? 그럼 버스로 하자.\n야마다: 응. 1박 2일로 절 같은 곳 돌아보자.\n스즈키: 좋다. 말차 디저트도 먹고 싶다.\n야마다: 물론! 그럼 자세한 건 다시 연락할게.\n스즈키: 응, 기대하고 있을게!',
  10
);

-- ============================================
-- N3 Scripts (sort_order 11-15)
-- ============================================

-- N3-1: 区役所での転入届
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '区役所での転入届',
  '窓口：いらっしゃいませ。どのようなご用件でしょうか。\n佐藤：先週、大阪から引っ越してきたので、転入届を出したいのですが。\n窓口：転入届ですね。前の住所の役所で転出届は出されましたか。\n佐藤：はい、転出証明書を持っています。\n窓口：ありがとうございます。では、こちらの用紙にご記入ください。新しい住所と、お名前、生年月日をお書きください。\n佐藤：はい。引っ越しの日付も書きますか。\n窓口：はい、実際に引っ越した日を書いてください。身分証明書はお持ちですか。\n佐藤：在留カードがあります。\n窓口：はい、結構です。在留カードの住所も変更が必要ですが、本日こちらで手続きできます。\n佐藤：ありがとうございます。住民票もすぐもらえますか。\n窓口：はい、手続きが終わりましたら、住民票を発行できます。一通三百円になります。\n佐藤：では、二通お願いします。\n窓口：かしこまりました。手続きに二十分ほどかかりますので、おかけになってお待ちください。\n佐藤：分かりました。よろしくお願いします。',
  'dialogue',
  'N3',
  ARRAY['窓口', '佐藤'],
  '区役所で転入届の手続きをする外国人の場面',
  '[{"word":"転入届","reading":"てんにゅうとどけ","meaning_ko":"전입신고"},{"word":"転出届","reading":"てんしゅつとどけ","meaning_ko":"전출신고"},{"word":"転出証明書","reading":"てんしゅつしょうめいしょ","meaning_ko":"전출증명서"},{"word":"在留カード","reading":"ざいりゅうカード","meaning_ko":"재류카드"},{"word":"住民票","reading":"じゅうみんひょう","meaning_ko":"주민표"},{"word":"発行","reading":"はっこう","meaning_ko":"발행"}]'::jsonb,
  '창구: 어서 오세요. 어떤 용건이신가요?\n사토: 지난주에 오사카에서 이사 왔는데, 전입신고를 하고 싶습니다.\n창구: 전입신고요. 이전 주소의 관청에서 전출신고는 하셨나요?\n사토: 네, 전출증명서를 가지고 있습니다.\n창구: 감사합니다. 그러면 이 용지에 기입해 주세요. 새 주소와 이름, 생년월일을 적어주세요.\n사토: 네. 이사 날짜도 쓰나요?\n창구: 네, 실제로 이사한 날을 적어주세요. 신분증은 가지고 계신가요?\n사토: 재류카드가 있습니다.\n창구: 네, 괜찮습니다. 재류카드의 주소도 변경이 필요한데, 오늘 여기서 수속할 수 있습니다.\n사토: 감사합니다. 주민표도 바로 받을 수 있나요?\n창구: 네, 수속이 끝나면 주민표를 발행할 수 있습니다. 한 통에 300엔입니다.\n사토: 그럼 두 통 부탁합니다.\n창구: 알겠습니다. 수속에 20분 정도 걸리니 앉아서 기다려 주세요.\n사토: 알겠습니다. 잘 부탁드립니다.',
  11
);

-- N3-2: 近所トラブルの相談
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '近所トラブルの相談',
  '管理人：はい、マンション管理事務所です。\n高橋：あの、三〇二号室の高橋です。ちょっとご相談があるのですが。\n管理人：高橋さん、どうされましたか。\n高橋：実は、上の階の方の足音がかなり気になっていまして。特に夜の十時過ぎに大きな音がするんです。\n管理人：それはお困りでしょうね。いつ頃からですか。\n高橋：先月から新しい方が越してきてからです。毎晩ではないんですが、週に三、四回くらいあります。\n管理人：分かりました。まず、全体のお知らせとして、夜間の騒音に関する注意書きを掲示板に貼りますね。\n高橋：直接言ったほうがいいでしょうか。\n管理人：最初は管理事務所から全体のお知らせという形が良いかと思います。それでも改善されない場合は、個別に対応いたします。\n高橋：分かりました。それでお願いします。\n管理人：何かあればまたいつでもご連絡ください。\n高橋：ありがとうございます。よろしくお願いします。',
  'phone_call',
  'N3',
  ARRAY['管理人', '高橋'],
  'マンション管理事務所に上階の騒音について電話で相談する場面',
  '[{"word":"管理人","reading":"かんりにん","meaning_ko":"관리인"},{"word":"足音","reading":"あしおと","meaning_ko":"발소리"},{"word":"騒音","reading":"そうおん","meaning_ko":"소음"},{"word":"掲示板","reading":"けいじばん","meaning_ko":"게시판"},{"word":"改善","reading":"かいぜん","meaning_ko":"개선"},{"word":"個別","reading":"こべつ","meaning_ko":"개별"}]'::jsonb,
  '관리인: 네, 맨션 관리사무소입니다.\n다카하시: 저, 302호실 다카하시입니다. 좀 상담할 게 있는데요.\n관리인: 다카하시 씨, 무슨 일이세요?\n다카하시: 사실, 윗층 분의 발소리가 꽤 신경 쓰여서요. 특히 밤 10시가 넘으면 큰 소리가 나요.\n관리인: 그건 곤란하시겠네요. 언제부터인가요?\n다카하시: 지난달에 새로운 분이 이사 오신 이후로요. 매일 밤은 아닌데 일주일에 서너 번 정도 있어요.\n관리인: 알겠습니다. 우선 전체 공지로 야간 소음에 관한 주의사항을 게시판에 붙이겠습니다.\n다카하시: 직접 말하는 게 좋을까요?\n관리인: 처음에는 관리사무소에서 전체 공지 형식이 좋을 것 같습니다. 그래도 개선되지 않으면 개별적으로 대응하겠습니다.\n다카하시: 알겠습니다. 그렇게 부탁합니다.\n관리인: 무슨 일이 있으면 언제든지 연락주세요.\n다카하시: 감사합니다. 잘 부탁드립니다.',
  12
);

-- N3-3: お祭りの案内放送
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'お祭りの案内放送',
  'アナウンス：皆さま、本日は第三十五回さくら祭りにお越しいただき、ありがとうございます。本日のスケジュールをご案内いたします。午前十時から正午まで、中央広場で和太鼓の演奏が行われます。午後一時からは、盆踊り大会を開催いたします。どなたでもご参加いただけます。また、会場の北側には屋台が並んでおりまして、焼きそば、たこ焼き、かき氷などをお楽しみいただけます。お子様向けには、南側の広場で金魚すくいや輪投げなどのゲームをご用意しております。なお、会場内は全面禁煙となっております。ゴミは所定のゴミ箱にお捨てください。花火大会は午後七時半から約三十分間行います。皆さま、最後までお楽しみください。',
  'announcement',
  'N3',
  ARRAY['アナウンス'],
  '地域のさくら祭りでの案内放送',
  '[{"word":"和太鼓","reading":"わだいこ","meaning_ko":"일본 북"},{"word":"盆踊り","reading":"ぼんおどり","meaning_ko":"봉오도리(일본 전통 춤)"},{"word":"屋台","reading":"やたい","meaning_ko":"포장마차"},{"word":"金魚すくい","reading":"きんぎょすくい","meaning_ko":"금붕어 잡기"},{"word":"全面禁煙","reading":"ぜんめんきんえん","meaning_ko":"전면 금연"},{"word":"花火大会","reading":"はなびたいかい","meaning_ko":"불꽃놀이 대회"}]'::jsonb,
  '안내방송: 여러분, 오늘 제35회 사쿠라 축제에 와주셔서 감사합니다. 오늘 일정을 안내해 드리겠습니다. 오전 10시부터 정오까지 중앙 광장에서 일본 북 연주가 있습니다. 오후 1시부터는 봉오도리 대회를 개최합니다. 누구나 참가하실 수 있습니다. 또한, 회장 북쪽에는 포장마차가 늘어서 있으며, 야키소바, 타코야키, 빙수 등을 즐기실 수 있습니다. 어린이들을 위해 남쪽 광장에서 금붕어 잡기와 고리 던지기 등의 게임을 준비하고 있습니다. 참고로 회장 내는 전면 금연입니다. 쓰레기는 지정된 쓰레기통에 버려주세요. 불꽃놀이 대회는 오후 7시 30분부터 약 30분간 진행됩니다. 여러분, 끝까지 즐겨주세요.',
  13
);

-- N3-4: 日本語教室での会話
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本語教室での会話',
  '先生：皆さん、今日は敬語の練習をしましょう。まず、尊敬語と謙譲語の違いを復習します。\nキム：先生、質問があります。「おっしゃる」と「申す」はどう使い分けますか。\n先生：いい質問ですね。「おっしゃる」は相手の動作に使う尊敬語で、「申す」は自分の動作に使う謙譲語です。例えば、「先生がおっしゃったこと」と「私が申したいこと」のように使います。\nキム：なるほど。日常生活ではどのくらい使いますか。\n先生：お店の店員さんとか、病院で話すときによく使いますよ。\nリン：先生、尊敬語と丁寧語はどう違いますか。\n先生：丁寧語は「です」「ます」のことで、誰に対しても使えます。尊敬語は相手を高める表現です。\nリン：じゃあ、友達には使わないほうがいいですか。\n先生：そうですね。友達に使うと距離を感じさせてしまいます。では、実際に練習してみましょう。ペアになってください。\nキム：はい。\n先生：一人がお客様役、もう一人が店員役です。自然な敬語で会話してみてください。',
  'dialogue',
  'N3',
  ARRAY['先生', 'キム', 'リン'],
  '日本語教室で敬語について学ぶ外国人学生と先生の会話',
  '[{"word":"敬語","reading":"けいご","meaning_ko":"경어"},{"word":"尊敬語","reading":"そんけいご","meaning_ko":"존경어"},{"word":"謙譲語","reading":"けんじょうご","meaning_ko":"겸양어"},{"word":"丁寧語","reading":"ていねいご","meaning_ko":"정중어"},{"word":"使い分ける","reading":"つかいわける","meaning_ko":"구분해서 사용하다"},{"word":"距離","reading":"きょり","meaning_ko":"거리"}]'::jsonb,
  '선생님: 여러분, 오늘은 경어 연습을 합시다. 우선 존경어와 겸양어의 차이를 복습합니다.\n김: 선생님, 질문이 있습니다. "おっしゃる"와 "申す"는 어떻게 구분해서 사용하나요?\n선생님: 좋은 질문이네요. "おっしゃる"는 상대방의 동작에 쓰는 존경어이고, "申す"는 자신의 동작에 쓰는 겸양어입니다. 예를 들어, "선생님이 말씀하신 것"과 "제가 말씀드리고 싶은 것"처럼 사용합니다.\n김: 그렇군요. 일상생활에서는 얼마나 사용하나요?\n선생님: 가게 점원이나 병원에서 이야기할 때 자주 사용해요.\n린: 선생님, 존경어와 정중어는 어떻게 다른가요?\n선생님: 정중어는 "です" "ます"를 말하는 것으로, 누구에게나 사용할 수 있어요. 존경어는 상대방을 높이는 표현입니다.\n린: 그럼 친구에게는 안 쓰는 게 좋나요?\n선생님: 맞아요. 친구에게 쓰면 거리감을 느끼게 합니다. 그러면 실제로 연습해 봅시다. 짝을 지어주세요.\n김: 네.\n선생님: 한 명이 손님 역, 다른 한 명이 점원 역입니다. 자연스러운 경어로 대화해 보세요.',
  14
);

-- N3-5: 災害時の避難案内
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '災害時の避難案内',
  'アナウンス：緊急のお知らせです。ただいま、この地域に大雨警報が発令されました。河川の水位が上昇しておりますので、川の近くにお住まいの方は十分にご注意ください。避難所は三か所開設されています。第一避難所は中央小学校、第二避難所は北区公民館、第三避難所は東体育館です。避難される方は、貴重品と水、食料を持って、落ち着いて行動してください。外が暗い場合は、懐中電灯をお持ちください。自動車での避難は道路が混雑する原因となりますので、できるだけ徒歩でお願いいたします。最新の情報は市の防災メールまたはラジオでご確認ください。皆さまの安全を第一にお考えください。繰り返します。この地域に大雨警報が発令されました。',
  'announcement',
  'N3',
  ARRAY['アナウンス'],
  '大雨警報発令時の地域防災放送',
  '[{"word":"警報","reading":"けいほう","meaning_ko":"경보"},{"word":"河川","reading":"かせん","meaning_ko":"하천"},{"word":"水位","reading":"すいい","meaning_ko":"수위"},{"word":"避難所","reading":"ひなんじょ","meaning_ko":"대피소"},{"word":"懐中電灯","reading":"かいちゅうでんとう","meaning_ko":"손전등"},{"word":"防災","reading":"ぼうさい","meaning_ko":"방재"}]'::jsonb,
  '안내방송: 긴급 안내입니다. 현재 이 지역에 호우경보가 발령되었습니다. 하천의 수위가 상승하고 있으니, 강 근처에 거주하시는 분들은 충분히 주의해 주세요. 대피소는 3곳이 개설되어 있습니다. 제1 대피소는 중앙초등학교, 제2 대피소는 북구 공민관, 제3 대피소는 동체육관입니다. 대피하시는 분은 귀중품과 물, 식량을 가지고 침착하게 행동해 주세요. 밖이 어두운 경우에는 손전등을 가져가세요. 자동차로 대피하시면 도로가 혼잡해지는 원인이 되니, 가능하면 도보로 부탁드립니다. 최신 정보는 시의 방재 메일 또는 라디오로 확인해 주세요. 여러분의 안전을 최우선으로 생각해 주세요. 반복합니다. 이 지역에 호우경보가 발령되었습니다.',
  15
);

-- ============================================
-- N2 Scripts (sort_order 16-20)
-- ============================================

-- N2-1: 市民講座の申し込み
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '市民講座の申し込み',
  '受付：はい、市民文化センターでございます。\n山田：あの、市民講座について問い合わせたいのですが。\n受付：はい、どのような講座をお探しでしょうか。\n山田：料理教室に興味がありまして。来月開講する講座はありますか。\n受付：来月ですと、「はじめての和食」と「家庭でできるイタリアン」の二講座がございます。\n山田：「はじめての和食」について詳しく教えていただけますか。\n受付：はい。毎週水曜日の午前十時から十二時まで、全八回のコースです。定員は十五名で、受講料は材料費込みで一万二千円になります。\n山田：申し込みはどのようにすればよろしいですか。\n受付：窓口での直接申し込みか、ホームページからのオンライン申し込みが可能です。なお、申し込み締め切りは今月の二十五日となっております。\n山田：定員にまだ空きはありますか。\n受付：現在のところ、まだ五名ほど空きがございます。\n山田：分かりました。持ち物は何か必要ですか。\n受付：エプロンと三角巾をご持参ください。調理器具と食材はこちらでご用意いたします。\n山田：ありがとうございます。では、オンラインで申し込ませていただきます。\n受付：はい、お待ちしております。ご不明な点がございましたら、いつでもお電話ください。',
  'phone_call',
  'N2',
  ARRAY['受付', '山田'],
  '市民文化センターに料理教室の講座について電話で問い合わせる場面',
  '[{"word":"開講","reading":"かいこう","meaning_ko":"개강"},{"word":"定員","reading":"ていいん","meaning_ko":"정원"},{"word":"受講料","reading":"じゅこうりょう","meaning_ko":"수강료"},{"word":"締め切り","reading":"しめきり","meaning_ko":"마감"},{"word":"三角巾","reading":"さんかくきん","meaning_ko":"삼각두건"},{"word":"調理器具","reading":"ちょうりきぐ","meaning_ko":"조리기구"}]'::jsonb,
  '접수: 네, 시민문화센터입니다.\n야마다: 저기, 시민강좌에 대해 문의하고 싶은데요.\n접수: 네, 어떤 강좌를 찾고 계신가요?\n야마다: 요리교실에 관심이 있는데요. 다음 달에 개강하는 강좌가 있나요?\n접수: 다음 달이면 "처음 시작하는 일식"과 "가정에서 만드는 이탈리안" 두 강좌가 있습니다.\n야마다: "처음 시작하는 일식"에 대해 자세히 알려주실 수 있나요?\n접수: 네. 매주 수요일 오전 10시부터 12시까지, 총 8회 코스입니다. 정원은 15명이고, 수강료는 재료비 포함 12,000엔입니다.\n야마다: 신청은 어떻게 하면 되나요?\n접수: 창구에서 직접 신청하시거나, 홈페이지에서 온라인 신청이 가능합니다. 참고로 신청 마감은 이달 25일입니다.\n야마다: 정원에 아직 자리가 있나요?\n접수: 현재로서는 아직 5명 정도 여유가 있습니다.\n야마다: 알겠습니다. 준비물은 뭐가 필요한가요?\n접수: 앞치마와 삼각두건을 지참해 주세요. 조리기구와 식재료는 저희 쪽에서 준비합니다.\n야마다: 감사합니다. 그럼 온라인으로 신청하겠습니다.\n접수: 네, 기다리고 있겠습니다. 불명확한 점이 있으시면 언제든지 전화해 주세요.',
  16
);

-- N2-2: 医師と患者の診察会話
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '医師と患者の診察会話',
  '医師：田中さん、先日の血液検査の結果が出ましたので、お伝えしますね。\n田中：はい、よろしくお願いします。\n医師：全体的に大きな問題はありませんが、コレステロール値がやや高めです。前回と比べると少し上がっています。\n田中：そうですか。何か生活で気をつけることはありますか。\n医師：まず、食生活の見直しが大切です。揚げ物や脂っこい食事を控えて、野菜を多く摂るようにしてください。\n田中：運動もしたほうがいいですか。\n医師：はい、ぜひ。毎日三十分程度のウォーキングをおすすめします。急に激しい運動をする必要はありませんが、継続的に体を動かすことが重要です。\n田中：分かりました。お酒はどうですか。\n医師：完全にやめる必要はありませんが、量を減らしてください。週に二日は休肝日を設けましょう。\n田中：薬は必要ですか。\n医師：今のところ、薬を出すほどではありません。まずは生活習慣の改善で様子を見ましょう。三か月後にもう一度検査をしますので、それまでに改善が見られなければ、その時に薬の処方を検討します。\n田中：分かりました。食事と運動、気をつけます。\n医師：あまり無理をせず、できることから始めてくださいね。次回は四月十五日でいかがですか。\n田中：はい、大丈夫です。ありがとうございました。',
  'dialogue',
  'N2',
  ARRAY['医師', '田中'],
  '健康診断の結果を踏まえて医師が生活改善を指導する場面',
  '[{"word":"血液検査","reading":"けつえきけんさ","meaning_ko":"혈액검사"},{"word":"コレステロール値","reading":"コレステロールち","meaning_ko":"콜레스테롤 수치"},{"word":"揚げ物","reading":"あげもの","meaning_ko":"튀김"},{"word":"継続的","reading":"けいぞくてき","meaning_ko":"지속적"},{"word":"休肝日","reading":"きゅうかんび","meaning_ko":"금주일"},{"word":"処方","reading":"しょほう","meaning_ko":"처방"}]'::jsonb,
  '의사: 다나카 씨, 며칠 전 혈액검사 결과가 나왔으니 알려드리겠습니다.\n다나카: 네, 부탁합니다.\n의사: 전체적으로 큰 문제는 없지만, 콜레스테롤 수치가 약간 높습니다. 전회와 비교하면 조금 올라갔어요.\n다나카: 그런가요. 생활에서 주의할 점이 있나요?\n의사: 우선 식생활 개선이 중요합니다. 튀김이나 기름진 식사를 줄이고, 채소를 많이 섭취하도록 해주세요.\n다나카: 운동도 하는 게 좋을까요?\n의사: 네, 꼭 하세요. 매일 30분 정도 걷기를 권장합니다. 갑자기 격렬한 운동을 할 필요는 없지만, 지속적으로 몸을 움직이는 것이 중요합니다.\n다나카: 알겠습니다. 술은 어떤가요?\n의사: 완전히 끊을 필요는 없지만, 양을 줄여주세요. 일주일에 이틀은 금주일을 만드세요.\n다나카: 약이 필요한가요?\n의사: 지금 당장은 약을 처방할 정도는 아닙니다. 우선 생활습관 개선으로 경과를 봅시다. 3개월 후에 다시 한번 검사를 하고, 그때까지 개선이 안 되면 그때 약 처방을 검토하겠습니다.\n다나카: 알겠습니다. 식사와 운동, 주의하겠습니다.\n의사: 너무 무리하지 마시고 할 수 있는 것부터 시작하세요. 다음은 4월 15일 어떠세요?\n다나카: 네, 괜찮습니다. 감사합니다.',
  17
);

-- N2-3: PTA会議での議論
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'PTA会議での議論',
  '会長：それでは、第三回PTA定例会議を始めます。本日の議題は、来月の運動会についてです。まず、日程の確認ですが、十月十二日の土曜日で変更はありませんね。\n副会長：はい、雨天の場合は翌日の十三日に延期ということで、学校側とも確認済みです。\n会長：ありがとうございます。次に、保護者のボランティアについてですが、現在何名集まっていますか。\n鈴木：現在、二十三名の申し出がありました。受付に五名、駐車場の誘導に四名、テント設営に六名、片付けに八名です。\n佐藤：すみません、救護班はどうなっていますか。看護師の資格を持っている方がいると安心なのですが。\n鈴木：救護班は学校の養護教諭が対応してくださいますが、補助として保護者の方にもお願いしたいと考えています。\n会長：では、次回までに救護班のボランティアも募集しましょう。それから、飲食の出店について何かご意見はありますか。\n佐藤：昨年はアレルギー対応が不十分だという声がありました。今年は各出店にアレルギー表示を義務付けてはどうでしょうか。\n副会長：賛成です。食品表示のテンプレートを作って配布するのがいいと思います。\n会長：では、そのように進めましょう。他にご質問やご意見はありますか。なければ、次回の会議は九月二十日に行います。本日はありがとうございました。',
  'meeting',
  'N2',
  ARRAY['会長', '副会長', '鈴木', '佐藤'],
  '小学校のPTA定例会議で運動会の準備を話し合う場面',
  '[{"word":"運動会","reading":"うんどうかい","meaning_ko":"운동회"},{"word":"雨天","reading":"うてん","meaning_ko":"우천"},{"word":"延期","reading":"えんき","meaning_ko":"연기"},{"word":"救護班","reading":"きゅうごはん","meaning_ko":"구호반"},{"word":"養護教諭","reading":"ようごきょうゆ","meaning_ko":"양호교사"},{"word":"アレルギー表示","reading":"アレルギーひょうじ","meaning_ko":"알레르기 표시"}]'::jsonb,
  '회장: 그러면 제3회 PTA 정례회의를 시작하겠습니다. 오늘의 의제는 다음 달 운동회에 대해서입니다. 우선 일정 확인인데, 10월 12일 토요일로 변경 없지요.\n부회장: 네, 우천 시에는 다음 날 13일로 연기하는 것으로 학교 측과도 확인 완료했습니다.\n회장: 감사합니다. 다음으로 학부모 봉사활동에 대해서인데, 현재 몇 명이 모였나요?\n스즈키: 현재 23명이 신청했습니다. 접수에 5명, 주차장 안내에 4명, 텐트 설치에 6명, 정리에 8명입니다.\n사토: 실례합니다만, 구호반은 어떻게 되어 있나요? 간호사 자격이 있는 분이 계시면 안심인데요.\n스즈키: 구호반은 학교 양호교사가 대응해 주시지만, 보조로 학부모 분께도 부탁하고 싶습니다.\n회장: 그러면 다음 회의까지 구호반 봉사자도 모집합시다. 그리고 음식 판매에 대해 의견이 있으신가요?\n사토: 작년에는 알레르기 대응이 불충분하다는 의견이 있었습니다. 올해는 각 판매점에 알레르기 표시를 의무화하는 것은 어떨까요?\n부회장: 찬성입니다. 식품 표시 템플릿을 만들어서 배포하는 게 좋겠습니다.\n회장: 그러면 그렇게 진행합시다. 다른 질문이나 의견이 있으신가요? 없으면 다음 회의는 9월 20일에 하겠습니다. 오늘 감사했습니다.',
  18
);

-- N2-4: 交通安全の講演
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '交通安全の講演',
  '講師：皆さん、こんにちは。本日は「身近な交通安全」というテーマでお話しさせていただきます。まず、昨年のこの地域の交通事故の統計をご覧ください。交通事故件数は前年より減少していますが、自転車に関する事故は逆に増加しています。特に、スマートフォンを見ながらの運転や、イヤホンをつけたままの走行が原因となるケースが目立ちます。自転車も車両の一種ですので、交通ルールを守る義務があります。具体的には、信号を守ること、一時停止の標識では必ず止まること、夜間は必ずライトを点灯すること、そして歩道ではなく車道の左側を走行することが基本です。また、最近は電動キックボードの事故も増えてきています。免許不要の区分であっても、ヘルメットの着用が推奨されています。お子さんがいらっしゃる方は、ぜひご家庭で交通安全について話し合ってみてください。小さなお子さんには、道路を渡るときは必ず手を挙げて、左右を確認してから渡るよう教えてあげてください。安全は一人一人の意識から始まります。ご清聴ありがとうございました。',
  'announcement',
  'N2',
  ARRAY['講師'],
  '地域の交通安全教室での講演',
  '[{"word":"統計","reading":"とうけい","meaning_ko":"통계"},{"word":"減少","reading":"げんしょう","meaning_ko":"감소"},{"word":"車両","reading":"しゃりょう","meaning_ko":"차량"},{"word":"一時停止","reading":"いちじていし","meaning_ko":"일시정지"},{"word":"点灯","reading":"てんとう","meaning_ko":"점등"},{"word":"着用","reading":"ちゃくよう","meaning_ko":"착용"}]'::jsonb,
  '강사: 여러분, 안녕하세요. 오늘은 "생활 속 교통안전"이라는 주제로 말씀드리겠습니다. 먼저, 작년 이 지역의 교통사고 통계를 보시겠습니다. 교통사고 건수는 전년보다 감소했지만, 자전거 관련 사고는 오히려 증가하고 있습니다. 특히 스마트폰을 보면서 운전하거나 이어폰을 끼고 주행하는 것이 원인이 되는 경우가 눈에 띕니다. 자전거도 차량의 일종이므로 교통 규칙을 지킬 의무가 있습니다. 구체적으로는 신호를 지키는 것, 일시정지 표지판에서는 반드시 멈추는 것, 야간에는 반드시 라이트를 켜는 것, 그리고 보도가 아닌 차도 왼쪽을 주행하는 것이 기본입니다. 또한 최근에는 전동 킥보드 사고도 늘어나고 있습니다. 면허 불요 구분이라 하더라도 헬멧 착용이 권장되고 있습니다. 자녀가 계신 분은 꼭 가정에서 교통안전에 대해 이야기해 보세요. 어린 자녀에게는 도로를 건널 때 반드시 손을 들고, 좌우를 확인한 후 건너도록 가르쳐 주세요. 안전은 한 사람 한 사람의 의식에서 시작됩니다. 경청해 주셔서 감사합니다.',
  19
);

-- N2-5: マンション管理組合の会合
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'マンション管理組合の会合',
  '理事長：それでは、マンション管理組合の臨時総会を開催いたします。本日の議題は、大規模修繕工事の実施計画についてです。\n副理事長：資料をお配りしましたので、ご確認ください。築二十年を迎えまして、外壁の塗装や防水工事が必要な時期となっております。\n住民A：工事費用はどの程度を見込んでいますか。\n理事長：見積もりを三社から取りまして、平均すると約三千万円になります。修繕積立金の残高は現在二千五百万円ですので、不足分は一時金として各戸にご負担いただく必要がございます。\n住民B：一戸あたりいくらになりますか。\n副理事長：全三十戸ですので、一戸あたり約十七万円のご負担となります。分割払いも検討しております。\n住民A：工事期間中はベランダが使えなくなるのでしょうか。\n理事長：足場を設置する関係で、各住戸のベランダが一週間から十日ほど使えなくなる期間がございます。洗濯物は室内に干していただくことになります。\n住民B：騒音はどの程度ですか。小さい子供がいるので心配です。\n副理事長：日中のみの作業で、土日は原則休工といたします。特に大きな騒音が出る作業の前には、事前にお知らせいたします。\n理事長：では、この計画について賛否をお聞きしたいと思います。賛成の方は挙手をお願いいたします。',
  'meeting',
  'N2',
  ARRAY['理事長', '副理事長', '住民A', '住民B'],
  'マンション管理組合の臨時総会で大規模修繕工事について話し合う場面',
  '[{"word":"大規模修繕","reading":"だいきぼしゅうぜん","meaning_ko":"대규모 수선"},{"word":"外壁","reading":"がいへき","meaning_ko":"외벽"},{"word":"修繕積立金","reading":"しゅうぜんつみたてきん","meaning_ko":"수선적립금"},{"word":"足場","reading":"あしば","meaning_ko":"비계, 발판"},{"word":"休工","reading":"きゅうこう","meaning_ko":"공사 중단"},{"word":"挙手","reading":"きょしゅ","meaning_ko":"거수"}]'::jsonb,
  '이사장: 그러면 맨션 관리조합 임시총회를 개최하겠습니다. 오늘의 의제는 대규모 수선공사 실시 계획에 대해서입니다.\n부이사장: 자료를 배포했으니 확인해 주세요. 건축 20년을 맞이하여, 외벽 도장이나 방수공사가 필요한 시기가 되었습니다.\n주민A: 공사 비용은 어느 정도 예상하고 있나요?\n이사장: 견적을 세 곳에서 받았는데, 평균 약 3,000만 엔입니다. 수선적립금 잔액은 현재 2,500만 엔이므로, 부족분은 일시금으로 각 세대에 부담해 주셔야 합니다.\n주민B: 세대당 얼마인가요?\n부이사장: 전체 30세대이므로, 세대당 약 17만 엔의 부담이 됩니다. 분할 납부도 검토하고 있습니다.\n주민A: 공사 기간 중에는 베란다를 사용할 수 없게 되나요?\n이사장: 비계를 설치하는 관계로, 각 세대 베란다를 1주일에서 열흘 정도 사용할 수 없는 기간이 있습니다. 빨래는 실내에서 말려주셔야 합니다.\n주민B: 소음은 어느 정도인가요? 어린 아이가 있어서 걱정됩니다.\n부이사장: 낮 시간에만 작업하고, 토일은 원칙적으로 공사를 중단합니다. 특히 큰 소음이 나는 작업 전에는 사전에 알려드리겠습니다.\n이사장: 그러면 이 계획에 대해 찬반을 묻고 싶습니다. 찬성하시는 분은 거수 부탁드립니다.',
  20
);

-- ============================================
-- N1 Scripts (sort_order 21-25)
-- ============================================

-- N1-1: 市長の施政方針演説
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '市長の施政方針演説',
  '市長：議員各位、並びに市民の皆さま、令和八年度の施政方針を申し述べます。当市は少子高齢化という構造的課題に直面しておりますが、これを危機ではなく変革の好機と捉え、持続可能なまちづくりを推進してまいります。第一に、子育て支援の抜本的強化です。待機児童ゼロの維持はもとより、第二子以降の保育料完全無償化を来年度から実施いたします。また、小中学校の給食費についても段階的に無償化し、子育て世帯の経済的負担を大幅に軽減いたします。第二に、高齢者福祉の充実です。地域包括ケアシステムをさらに拡充し、在宅医療と介護の連携を強化いたします。各地区に設置しております高齢者サロンを現在の十五か所から二十五か所に増設し、高齢者の社会参加と生きがいづくりを支援いたします。第三に、防災・減災対策の強化です。近年の気候変動による自然災害の激甚化を踏まえ、河川の堤防強化や排水設備の整備に重点的に予算を配分いたします。さらに、全市民を対象としたハザードマップの更新と防災訓練の拡充を図ります。これらの施策の財源については、行財政改革による歳出の見直しと、ふるさと納税の活用により確保してまいります。市民の皆さまのご理解とご協力を賜りますようお願い申し上げます。',
  'announcement',
  'N1',
  ARRAY['市長'],
  '市議会における市長の年度施政方針演説',
  '[{"word":"施政方針","reading":"しせいほうしん","meaning_ko":"시정방침"},{"word":"少子高齢化","reading":"しょうしこうれいか","meaning_ko":"저출산 고령화"},{"word":"待機児童","reading":"たいきじどう","meaning_ko":"대기아동"},{"word":"地域包括ケア","reading":"ちいきほうかつケア","meaning_ko":"지역포괄케어"},{"word":"激甚化","reading":"げきじんか","meaning_ko":"격심화"},{"word":"行財政改革","reading":"ぎょうざいせいかいかく","meaning_ko":"행재정 개혁"}]'::jsonb,
  '시장: 의원 여러분, 그리고 시민 여러분, 레이와 8년도 시정방침을 말씀드리겠습니다. 본 시는 저출산 고령화라는 구조적 과제에 직면해 있으나, 이를 위기가 아닌 변혁의 기회로 삼아 지속 가능한 도시 만들기를 추진해 나가겠습니다. 첫째, 육아 지원의 근본적 강화입니다. 대기아동 제로 유지는 물론이고, 둘째 자녀 이후의 보육료 완전 무상화를 내년도부터 실시하겠습니다. 또한 초중학교 급식비에 대해서도 단계적으로 무상화하여 육아 세대의 경제적 부담을 대폭 경감하겠습니다. 둘째, 고령자 복지의 충실입니다. 지역포괄케어시스템을 더욱 확충하고, 재택의료와 돌봄의 연계를 강화하겠습니다. 각 지구에 설치한 고령자 살롱을 현재 15곳에서 25곳으로 증설하여, 고령자의 사회참여와 보람 만들기를 지원하겠습니다. 셋째, 방재·감재 대책의 강화입니다. 최근 기후변동으로 인한 자연재해의 격심화를 감안하여, 하천 제방 강화와 배수 시설 정비에 중점적으로 예산을 배정하겠습니다. 나아가 전 시민을 대상으로 한 해저드맵 업데이트와 방재 훈련 확충을 도모하겠습니다. 이러한 시책의 재원에 대해서는 행재정 개혁을 통한 세출 재검토와 고향 납세 활용으로 확보해 나가겠습니다. 시민 여러분의 이해와 협조를 부탁드립니다.',
  21
);

-- N1-2: 文化交流シンポジウム
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '文化交流シンポジウム',
  '司会：本日は「多文化共生社会の実現に向けて」と題しまして、シンポジウムを開催いたします。まず、基調講演をお願いいたします。\n教授：ご紹介いただきました東京大学の山田です。日本における外国人住民の数は年々増加しており、多文化共生は避けて通れない社会課題となっています。しかし、共生という言葉が示すように、これは一方的な同化ではなく、相互理解と尊重に基づく関係の構築を意味します。\n司会：ありがとうございます。次に、パネリストの方々にお話しいただきます。\nパネリストA：私は地域の国際交流協会で活動しています。外国人住民の方々が最も困っているのは、やはり言葉の壁です。日本語教室を運営していますが、ボランティアの確保が課題です。また、災害時の多言語対応も急務となっています。\nパネリストB：教育の観点からお話しします。外国にルーツを持つ子どもたちの学習支援が不可欠です。日本語が十分でないために授業についていけず、不登校になるケースも少なくありません。母語教育の機会も保障すべきだと考えます。\n教授：お二人のご指摘は非常に重要です。制度的な整備に加えて、地域レベルでの草の根の交流こそが、真の共生社会を実現する鍵ではないでしょうか。お互いの文化を知り、日常的な接点を増やしていくことが、偏見や差別を克服する最も有効な手段だと確信しています。\n司会：貴重なご意見をありがとうございました。会場からのご質問を受け付けます。',
  'meeting',
  'N1',
  ARRAY['司会', '教授', 'パネリストA', 'パネリストB'],
  '多文化共生をテーマとした学術シンポジウム',
  '[{"word":"多文化共生","reading":"たぶんかきょうせい","meaning_ko":"다문화 공생"},{"word":"基調講演","reading":"きちょうこうえん","meaning_ko":"기조강연"},{"word":"同化","reading":"どうか","meaning_ko":"동화"},{"word":"急務","reading":"きゅうむ","meaning_ko":"급선무"},{"word":"不登校","reading":"ふとうこう","meaning_ko":"학교 부적응(미등교)"},{"word":"偏見","reading":"へんけん","meaning_ko":"편견"}]'::jsonb,
  '사회자: 오늘은 "다문화 공생 사회의 실현을 향하여"라는 주제로 심포지엄을 개최합니다. 먼저 기조강연을 부탁드리겠습니다.\n교수: 소개받은 도쿄대학의 야마다입니다. 일본에서의 외국인 주민 수는 해마다 증가하고 있으며, 다문화 공생은 피할 수 없는 사회적 과제가 되었습니다. 그러나 공생이라는 말이 보여주듯이, 이것은 일방적인 동화가 아니라 상호 이해와 존중에 기반한 관계 구축을 의미합니다.\n사회자: 감사합니다. 다음으로 패널리스트 분들에게 말씀을 듣겠습니다.\n패널리스트A: 저는 지역 국제교류협회에서 활동하고 있습니다. 외국인 주민들이 가장 곤란해하는 것은 역시 언어의 벽입니다. 일본어 교실을 운영하고 있지만 자원봉사자 확보가 과제입니다. 또한 재해 시 다국어 대응도 급선무가 되고 있습니다.\n패널리스트B: 교육 관점에서 말씀드리겠습니다. 외국에 뿌리를 둔 아이들의 학습 지원이 불가결합니다. 일본어가 충분하지 않아 수업을 따라가지 못하고, 미등교가 되는 경우도 적지 않습니다. 모국어 교육의 기회도 보장해야 한다고 생각합니다.\n교수: 두 분의 지적은 매우 중요합니다. 제도적 정비에 더하여, 지역 수준의 풀뿌리 교류야말로 진정한 공생 사회를 실현하는 열쇠가 아닐까요. 서로의 문화를 알고 일상적인 접점을 늘려가는 것이 편견과 차별을 극복하는 가장 유효한 수단이라고 확신합니다.\n사회자: 귀중한 의견 감사합니다. 회장에서의 질문을 받겠습니다.',
  22
);

-- N1-3: 地域活性化の座談会
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '地域活性化の座談会',
  '進行：本日は「人口減少時代における地域活性化」というテーマで座談会を行います。まず、田中さんから現状をお聞かせください。\n田中：当町の人口はこの二十年で三割減少しました。特に若年層の流出が深刻で、高校を卒業すると大半が都市部に出てしまいます。商店街もシャッター通りと化し、かつての賑わいは見る影もありません。\n山本：私は隣の村で農業を営んでいますが、後継者不足は切実な問題です。ただ、最近は都会からの移住者がわずかながら増えてきていまして、新規就農者の受け入れ体制を整えることで、地域に新しい風を吹き込めるのではないかと考えています。\n佐藤：観光の立場から申し上げますと、当地域にはまだ十分に活用されていない観光資源が数多くあります。温泉や伝統工芸、豊かな自然環境を組み合わせた体験型の滞在プログラムを開発することで、交流人口の拡大を図れるのではないでしょうか。\n田中：確かに、定住人口だけでなく関係人口という考え方も重要ですね。地域に関わる人を増やすことが、結果的に移住者の増加にもつながるかもしれません。\n山本：デジタル技術の活用も欠かせません。オンラインでの特産品販売や、リモートワーク環境の整備によって、場所に縛られない働き方を実現できれば、地方の可能性は広がります。\n進行：皆さんのおっしゃるように、一つの施策だけでなく、複合的なアプローチが求められているわけですね。行政としても、民間の創意工夫を後押しする柔軟な支援制度の構築が急がれます。\n佐藤：補助金に頼るだけでなく、地域自らが稼ぐ力をつけることが持続可能性の観点からも不可欠だと思います。\n田中：おっしゃる通りです。地域の課題を地域の強みに変えていく発想の転換こそが、これからの活性化の鍵になるでしょう。',
  'meeting',
  'N1',
  ARRAY['進行', '田中', '山本', '佐藤'],
  '地域の課題と活性化策について話し合う座談会',
  '[{"word":"過疎化","reading":"かそか","meaning_ko":"과소화"},{"word":"後継者","reading":"こうけいしゃ","meaning_ko":"후계자"},{"word":"関係人口","reading":"かんけいじんこう","meaning_ko":"관계인구"},{"word":"特産品","reading":"とくさんひん","meaning_ko":"특산품"},{"word":"創意工夫","reading":"そういくふう","meaning_ko":"창의적 궁리"},{"word":"発想の転換","reading":"はっそうのてんかん","meaning_ko":"발상의 전환"}]'::jsonb,
  '진행: 오늘은 "인구감소 시대의 지역 활성화"라는 주제로 좌담회를 진행합니다. 먼저 다나카 씨부터 현황을 말씀해 주세요.\n다나카: 우리 마을 인구는 지난 20년간 30% 감소했습니다. 특히 젊은 층의 유출이 심각해서, 고등학교를 졸업하면 대부분 도시로 나가버립니다. 상점가도 셔터 거리가 되어 예전의 활기는 흔적도 없습니다.\n야마모토: 저는 이웃 마을에서 농업을 하고 있는데, 후계자 부족은 절실한 문제입니다. 다만 최근에는 도시에서의 이주자가 조금씩 늘고 있어서, 신규 취농자 수용 체제를 갖추면 지역에 새바람을 불어넣을 수 있지 않을까 생각합니다.\n사토: 관광 입장에서 말씀드리면, 이 지역에는 아직 충분히 활용되지 않은 관광 자원이 많이 있습니다. 온천이나 전통 공예, 풍요로운 자연환경을 조합한 체험형 체재 프로그램을 개발하면 교류 인구 확대를 도모할 수 있지 않을까요.\n다나카: 확실히 정주 인구만이 아니라 관계인구라는 사고방식도 중요하네요. 지역에 관여하는 사람을 늘리는 것이 결과적으로 이주자 증가로도 이어질 수 있겠습니다.\n야마모토: 디지털 기술 활용도 빠뜨릴 수 없습니다. 온라인 특산품 판매나 원격근무 환경 정비를 통해 장소에 구애받지 않는 일하는 방식을 실현할 수 있다면, 지방의 가능성은 넓어집니다.\n진행: 여러분 말씀대로, 하나의 시책만이 아니라 복합적인 접근이 요구되고 있군요. 행정 측에서도 민간의 창의적 궁리를 뒷받침하는 유연한 지원 제도 구축이 시급합니다.\n사토: 보조금에만 의존하지 않고, 지역 스스로 수익을 낼 수 있는 힘을 기르는 것이 지속가능성 관점에서도 불가결하다고 생각합니다.\n다나카: 말씀하신 대로입니다. 지역의 과제를 지역의 강점으로 바꾸는 발상의 전환이야말로 앞으로의 활성화의 열쇠가 될 것입니다.',
  23
);

-- N1-4: 教育改革についての討論
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '教育改革についての討論',
  '司会：本日は「これからの教育のあるべき姿」について討論していただきます。まず、現在の教育の課題について、各パネリストの見解をお聞かせください。\n教授A：最大の課題は、画一的な教育から個別最適化された学びへの転換が進んでいないことです。子どもたちの学習速度や興味関心は多様であるにもかかわらず、一律の教科書、一律のペースで授業が進められています。\n教授B：私はむしろ、教育の本質的な目的が見失われていることを懸念しています。知識の暗記偏重から脱却できず、批判的思考力や創造性を育む教育が不十分です。変化の激しい時代において、自ら問いを立て、多角的に考える力こそが求められているはずです。\n保護者代表：現場の声として申し上げますと、教員の多忙化が子どもたちの教育の質に直接影響しています。教員が一人一人の子どもと向き合う時間が不足しています。部活動の指導や事務作業の負担を軽減しなければ、いくら理想を掲げても実現は困難です。\n教授A：おっしゃる通りです。教育改革は教員の働き方改革と表裏一体の関係にあります。また、地域格差の問題も看過できません。都市部と地方では、教育資源に大きな開きがあります。\n教授B：デジタル技術は地域格差を埋める有力な手段となり得ます。ただし、対面での対話やグループ活動を通じて培われる社会性やコミュニケーション能力は、デジタルでは代替できません。技術の活用と人間的な関わりのバランスが極めて重要です。\n司会：それぞれのお立場から貴重なご意見をいただきました。教育は社会の根幹を成すものであり、この議論を一過性のものとせず、継続的に対話を重ねていく必要がありますね。\n保護者代表：子どもたちの未来のために、理想論だけでなく、実行可能な具体策を早急に講じていただきたいと切に願っております。',
  'meeting',
  'N1',
  ARRAY['司会', '教授A', '教授B', '保護者代表'],
  '教育改革の方向性について専門家と保護者が討論するパネルディスカッション',
  '[{"word":"画一的","reading":"かくいつてき","meaning_ko":"획일적"},{"word":"暗記偏重","reading":"あんきへんちょう","meaning_ko":"암기 편중"},{"word":"批判的思考力","reading":"ひはんてきしこうりょく","meaning_ko":"비판적 사고력"},{"word":"表裏一体","reading":"ひょうりいったい","meaning_ko":"표리일체"},{"word":"看過","reading":"かんか","meaning_ko":"간과"},{"word":"一過性","reading":"いっかせい","meaning_ko":"일시적"}]'::jsonb,
  '사회자: 오늘은 "앞으로의 교육이 나아가야 할 방향"에 대해 토론해 주시겠습니다. 먼저 현재 교육의 과제에 대해 각 패널리스트의 견해를 들려주세요.\n교수A: 최대 과제는 획일적 교육에서 개별 최적화된 배움으로의 전환이 진행되지 않고 있다는 것입니다. 아이들의 학습 속도와 흥미 관심은 다양함에도 불구하고, 일률적인 교과서와 일률적인 속도로 수업이 진행되고 있습니다.\n교수B: 저는 오히려 교육의 본질적 목적이 상실되고 있는 것을 우려합니다. 지식 암기 편중에서 벗어나지 못하고, 비판적 사고력과 창의성을 기르는 교육이 불충분합니다. 변화가 격렬한 시대에 스스로 질문을 세우고 다각적으로 생각하는 힘이야말로 요구되는 것입니다.\n학부모 대표: 현장의 목소리로 말씀드리면, 교원의 과다 업무가 아이들의 교육 질에 직접 영향을 미치고 있습니다. 교원이 한 명 한 명의 아이와 마주할 시간이 부족합니다. 부활동 지도나 사무 작업의 부담을 줄이지 않으면, 아무리 이상을 내세워도 실현은 곤란합니다.\n교수A: 말씀하신 대로입니다. 교육 개혁은 교원의 근무 방식 개혁과 표리일체 관계에 있습니다. 또한 지역 격차 문제도 간과할 수 없습니다. 도시부와 지방에서는 교육 자원에 큰 차이가 있습니다.\n교수B: 디지털 기술은 지역 격차를 메우는 유력한 수단이 될 수 있습니다. 다만 대면 대화나 그룹 활동을 통해 길러지는 사회성과 커뮤니케이션 능력은 디지털로 대체할 수 없습니다. 기술 활용과 인간적 관계의 균형이 매우 중요합니다.\n사회자: 각각의 입장에서 귀중한 의견을 주셨습니다. 교육은 사회의 근간을 이루는 것이므로, 이 논의를 일회성으로 끝내지 않고 지속적으로 대화를 거듭해 나갈 필요가 있겠습니다.\n학부모 대표: 아이들의 미래를 위해 이상론만이 아닌 실행 가능한 구체적 대책을 조속히 마련해 주시기를 간절히 바랍니다.',
  24
);

-- N1-5: 環境保護NPOの活動報告
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '環境保護NPOの活動報告',
  '代表：皆さま、NPO法人「緑の地球を守る会」の年次活動報告をいたします。本年度は三つの重点事業に取り組んでまいりました。第一の事業は、里山再生プロジェクトです。荒廃していた市内五か所の里山において、地域住民とボランティアの協力のもと、間伐作業や植樹活動を実施しました。延べ参加人数は千二百名に達し、約三千本の苗木を植えることができました。生態系の回復も確認されており、絶滅が危惧されていたオオタカの営巣も観察されています。\n事務局長：第二の事業は、環境教育プログラムの推進です。市内の小中学校二十三校において、出前授業を実施しました。生物多様性の大切さや、身近にできるエコ活動について、体験を交えながら学んでいただきました。特に好評だったのが、河川の水質調査を子どもたち自身が行うプログラムで、科学的な探究心を育むとともに、地域の環境への関心を高めることができました。\n代表：第三の事業は、プラスチックごみ削減キャンペーンです。地元企業十五社と連携し、マイボトル・マイバッグの普及促進を行いました。また、海岸清掃活動を月一回実施し、年間で約二トンのごみを回収しました。課題としましては、活動資金の確保が依然として厳しい状況にあります。会員数は増加傾向にあるものの、助成金への依存度が高く、自主財源の多様化が必要です。\n事務局長：来年度の展望としましては、企業との協働事業の拡大や、クラウドファンディングの活用など、新たな資金調達の仕組みを構築してまいります。また、他地域のNPOとのネットワーク強化を通じて、活動の広域化を目指します。\n代表：持続可能な社会の実現は、一朝一夕に達成できるものではありません。しかし、地道な活動の積み重ねが、確実に地域を変えつつあることを実感しております。引き続き皆さまのご支援を賜りますようお願い申し上げます。',
  'announcement',
  'N1',
  ARRAY['代表', '事務局長'],
  '環境保護NPOの年次総会での活動報告',
  '[{"word":"里山","reading":"さとやま","meaning_ko":"마을 뒷산(전통적 농촌 산림)"},{"word":"間伐","reading":"かんばつ","meaning_ko":"간벌"},{"word":"生態系","reading":"せいたいけい","meaning_ko":"생태계"},{"word":"生物多様性","reading":"せいぶつたようせい","meaning_ko":"생물다양성"},{"word":"助成金","reading":"じょせいきん","meaning_ko":"보조금"},{"word":"一朝一夕","reading":"いっちょういっせき","meaning_ko":"하루아침"}]'::jsonb,
  '대표: 여러분, NPO법인 "녹색 지구를 지키는 모임"의 연차 활동 보고를 드리겠습니다. 본 연도는 세 가지 중점 사업에 힘써왔습니다. 첫 번째 사업은 마을산 재생 프로젝트입니다. 황폐해져 있던 시내 5곳의 마을산에서, 지역 주민과 자원봉사자의 협력 아래 간벌 작업과 식수 활동을 실시했습니다. 연인원 참가자 수는 1,200명에 달했으며, 약 3,000그루의 묘목을 심을 수 있었습니다. 생태계 회복도 확인되고 있으며, 멸종이 우려되던 참매의 영소도 관찰되고 있습니다.\n사무국장: 두 번째 사업은 환경 교육 프로그램의 추진입니다. 시내 초중학교 23개교에서 찾아가는 수업을 실시했습니다. 생물다양성의 소중함과 생활 속에서 할 수 있는 에코 활동에 대해, 체험을 곁들이며 배워주셨습니다. 특히 호평이었던 것은 하천 수질조사를 아이들 스스로 하는 프로그램으로, 과학적 탐구심을 기르는 동시에 지역 환경에 대한 관심을 높일 수 있었습니다.\n대표: 세 번째 사업은 플라스틱 쓰레기 감축 캠페인입니다. 지역 기업 15곳과 연계하여 개인 물병·개인 가방의 보급 촉진을 했습니다. 또한 해안 청소 활동을 월 1회 실시하여, 연간 약 2톤의 쓰레기를 수거했습니다. 과제로는 활동 자금 확보가 여전히 어려운 상황에 있습니다. 회원 수는 증가 추세에 있지만, 보조금 의존도가 높아 자주 재원의 다양화가 필요합니다.\n사무국장: 내년도 전망으로는, 기업과의 협업 사업 확대나 크라우드펀딩 활용 등, 새로운 자금 조달 방법을 구축해 나가겠습니다. 또한 다른 지역 NPO와의 네트워크 강화를 통해 활동의 광역화를 목표로 합니다.\n대표: 지속 가능한 사회의 실현은 하루아침에 달성할 수 있는 것이 아닙니다. 그러나 꾸준한 활동의 축적이 확실히 지역을 변화시키고 있음을 실감하고 있습니다. 계속해서 여러분의 지원을 부탁드립니다.',
  25
);
